export default function CommunityRulesPage() { return <main className="page-shell policy"><p className="eyebrow">COMMUNITY RULES</p><h1 className="page-title">Keep the public record useful.</h1><h2>What belongs here</h2><p>Source-backed information, relevant news clips, public documents, clearly labeled analysis, questions, and respectful discussion connected to a real topic.</p><h2>What gets removed</h2><p>Private personal information, phone numbers, addresses, sexual content, harassment, hate speech, racist or sexist content, threats, unrelated video, unsupported accusations, and misleading material.</p><h2>Discussion access</h2><p>Discussion spaces require an account. Repeated or serious violations may result in a temporary suspension or removal. Final enforcement rules and appeals must be set before launch.</p></main>; }
